mock.script:
set build [file normalize $env(V109_EXPORT_CHECK_DIR)]
source [file join $build inputs.tcl]
if {$start_mode ne "rtl" || $part ne "xc7a100tcsg324-1"} {error "part/start mismatch"}
if {[llength $rtl_sources]!=17} {error "RTL count"}
foreach p $rtl_sources {
 if {![file isfile $p] || [string first [file join $build snapshot] $p]!=0} {error "nonlocal RTL $p"}
 puts "RTL\t$p"
}
foreach p $include_dirs {
 if {![file isdirectory $p] || [string first [file join $build snapshot] $p]!=0} {error "nonlocal include $p"}
 puts "INCLUDE\t$p"
}
if {$constraint_file ne [file join $build component.xdc] || ![file isfile $constraint_file]} {error "constraint path"}
puts "PART\t$part"
puts "START\t$start_mode"
puts "TRIAL\t$trial_id"
puts "DIRECTIVES\t$opt_directive,$place_directive,$phys_directive,$route_directive"
puts "CONSTRAINT\t$constraint_file"
puts "STATUS\tPASS_MOCK_INPUTS_TCL_NO_VIVADO"
